/**
 * Downtime log core — the pure formatting and grouping half of the downtime
 * log. Split from downtime-log.mjs the same way downtime-core is split from
 * downtime-app: everything here runs under `node --test` on plain objects.
 *
 * No Foundry globals, no Date.now(), no Math.random. Every timestamp is the
 * ISO string the caller supplied, so a rendered row is reproducible.
 *
 * Ships no rules text: slot labels come from the skeleton (module-authored,
 * <=5 words) and the effect summary is generated by downtime-effects.mjs.
 */

import { esc } from "../shared/esc.mjs";

/** Marks the per-day section heading so grouping never depends on its text. */
export const DAY_ATTR = "data-sde-day";

/**
 * Normalize a caller-supplied entry into the shape both sinks render from.
 * Missing fields degrade to something printable rather than throwing — the
 * log must never be the reason a downtime roll fails.
 */
export function normalizeEntry(raw) {
  // `Number(null)` is 0, so an absent roll would otherwise print as "0 vs DC
  // 18" — a failure that never happened. Absent stays absent.
  const num = (v) => {
    if (v === null || v === undefined || v === "") return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  };
  return {
    actorId: raw?.actorId ?? null,
    actorName: String(raw?.actorName ?? "Someone"),
    player: String(raw?.player ?? "GM"),
    sourceSlug: raw?.sourceSlug ?? null,
    slotKey: raw?.slotKey ?? null,
    slotLabel: String(raw?.slotLabel ?? raw?.slotKey ?? "Downtime activity"),
    activityKey: raw?.activityKey ?? null,
    activityName: String(raw?.activityName ?? "Downtime"),
    total: num(raw?.total),
    dc: num(raw?.dc),
    success: !!raw?.success,
    costGp: Math.max(0, num(raw?.costGp) ?? 0),
    effectSummary: String(raw?.effectSummary ?? "").trim(),
    gmRolled: !!raw?.gmRolled,
    timestamp: typeof raw?.timestamp === "string" && raw.timestamp ? raw.timestamp : null,
  };
}

/* ────────────────────────────────────────────────────────────────────────── */
/* Time helpers                                                               */
/* ────────────────────────────────────────────────────────────────────────── */

const pad2 = (n) => String(n).padStart(2, "0");

/**
 * Local calendar day of an ISO instant, as `YYYY-MM-DD`.
 *
 * Deliberately LOCAL, not UTC: the heading groups a table's real-world play
 * day, and a session that runs past midnight UTC is still "tonight" to the
 * people at the table. Returns null for an unparseable input.
 */
export function dayKey(iso) {
  const d = new Date(iso ?? "");
  if (Number.isNaN(d.getTime())) return null;
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}

/** Local `HH:MM` of an ISO instant, or "" when unparseable. */
export function timeOfDay(iso) {
  const d = new Date(iso ?? "");
  if (Number.isNaN(d.getTime())) return "";
  return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
}

/* ────────────────────────────────────────────────────────────────────────── */
/* Row text                                                                   */
/* ────────────────────────────────────────────────────────────────────────── */

/** `19 vs DC 18` — or just the DC when the roll is missing. */
function checkText(e) {
  if (e.total == null && e.dc == null) return "";
  if (e.total == null) return `DC ${e.dc}`;
  if (e.dc == null) return `rolled ${e.total}`;
  return `${e.total} vs DC ${e.dc}`;
}

/**
 * The Session Recap headline row, PLAIN TEXT (Handlebars escapes it, and the
 * Discord export wants markdown-safe plain text):
 *
 *   `Bazogo — New weapon (d6 max): 19 vs DC 18, success, 50 gp`
 *
 * The effect summary is deliberately NOT folded in here — it is rendered as
 * its own muted sub-line so the headline stays scannable.
 */
export function recapRow(entry) {
  const e = normalizeEntry(entry);
  const parts = [];
  const check = checkText(e);
  if (check) parts.push(check);
  parts.push(e.success ? "success" : "failure");
  if (e.costGp > 0) parts.push(`${e.costGp} gp`);
  return `${e.actorName} — ${e.slotLabel}: ${parts.join(", ")}`;
}

/** Shared trailing markers: who rolled it, and which book it came from. */
function metaSuffix(e) {
  const bits = [];
  if (e.gmRolled) bits.push("GM");
  if (e.sourceSlug) bits.push(e.sourceSlug);
  return bits.length ? ` (${bits.join(" · ")})` : "";
}

/**
 * One journal `<li>`. Every interpolated value is escaped — slot labels are
 * module-authored but the effect summary can carry an item name a user typed.
 */
export function journalRow(entry) {
  const e = normalizeEntry(entry);
  const time = timeOfDay(e.timestamp);
  const timeCell = time ? `<strong>${esc(time)}</strong> — ` : "";
  const check = checkText(e);
  const verdict = e.success ? "success" : "failure";
  const bits = [];
  if (check) bits.push(esc(check));
  bits.push(verdict);
  if (e.costGp > 0) bits.push(`${e.costGp} gp`);
  const effect = e.effectSummary ? ` <em>${esc(e.effectSummary)}</em>` : "";
  return `<li>${timeCell}<strong>${esc(e.actorName)}</strong> · ${esc(e.activityName)} — `
    + `${esc(e.slotLabel)}: ${bits.join(", ")}${esc(metaSuffix(e))}${effect}</li>`;
}

/* ────────────────────────────────────────────────────────────────────────── */
/* Journal page assembly                                                      */
/* ────────────────────────────────────────────────────────────────────────── */

/**
 * Insert `rowHtml` into `html` under the `day` heading, creating the day's
 * section when it is not there yet.
 *
 * ORDERING (one rule, applied everywhere): NEWEST FIRST. A new day's section
 * is prepended above the previous days, and a new row is prepended inside its
 * own day. The most recent downtime is always the first thing on the page.
 *
 * Pure string surgery — no DOM, so this runs in node. The day marker is the
 * `data-sde-day` attribute, never the heading's visible text, so re-labelling
 * a heading by hand can't split a day in two.
 */
export function insertRow(html, day, rowHtml) {
  const existing = typeof html === "string" ? html : "";
  if (!day) return existing;

  // Find this day's section: <h2 data-sde-day="…"> followed by its <ul>.
  const headingRe = new RegExp(`<h2[^>]*${DAY_ATTR}="${escapeAttr(day)}"[^>]*>`, "i");
  const headingMatch = existing.match(headingRe);
  if (headingMatch) {
    const afterHeading = headingMatch.index + headingMatch[0].length;
    const ulMatch = existing.slice(afterHeading).match(/<ul[^>]*>/i);
    if (ulMatch) {
      const at = afterHeading + ulMatch.index + ulMatch[0].length;
      return existing.slice(0, at) + rowHtml + existing.slice(at);
    }
    // Heading exists but its list was removed by hand — rebuild the list.
    return existing.slice(0, afterHeading) + `<ul>${rowHtml}</ul>` + existing.slice(afterHeading);
  }

  return daySection(day, rowHtml) + existing;
}

/** A fresh day block. The visible label IS the sortable key — no ambiguity. */
export function daySection(day, rowsHtml = "") {
  return `<h2 ${DAY_ATTR}="${escapeAttr(day)}">${esc(day)}</h2><ul>${rowsHtml}</ul>`;
}

/** Attribute-safe day key (it is always `YYYY-MM-DD`, but never assume). */
function escapeAttr(v) {
  return String(v ?? "").replace(/"/g, "&quot;");
}

/** Count the rows on a page — used by the live check and by the tests. */
export function countRows(html) {
  return (String(html ?? "").match(/<li\b/gi) ?? []).length;
}

/**
 * Build a whole page from scratch out of entries (newest first). Used for the
 * first write and by tests; the normal path is incremental via insertRow.
 */
export function buildPage(entries) {
  let html = "";
  for (const entry of entries) {
    const e = normalizeEntry(entry);
    const day = dayKey(e.timestamp);
    if (!day) continue;
    html = insertRow(html, day, journalRow(e));
  }
  return html;
}
